entries[45589] = { ["name"] = "Gnomeregan Mechanostrider", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"When you absolutely, positively have to be there right now. -Rillie Spindlenut\"\nVendor:\nRillie Spindlenut\nZone:\nIcecrown\nCost:\n100" }
entries[45590] = { ["name"] = "Exodar Elekk", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Exodar Elekk are elekk which have been anointed by O'ros, the Naaru who journeyed from Draenor to Azeroth with Velen and his followers.\"\nVendor:\nIrisee\nZone:\nIcecrown\nCost:\n100" }
entries[45591] = { ["name"] = "Darnassian Nightsaber", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"When a night elf's mount perishes, it is custom for the rider to keep one of the saber's great fangs as a token of remembrance.\"\nVendor:\nRook Hawkfist\nZone:\nIcecrown\nCost:\n100" }
entries[45592] = { ["name"] = "Thunder Bluff Kodo", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"An alpha member of the herd, this kodo is a prime example of the mighty creatures which thunder through Mulgore.\"\nVendor:\nDoru Thunderhorn\nZone:\nIcecrown\nCost:\n100" }
